        foreach ($candidates as $c) {
            $hrId = $c['hr_id'] ?? 1;

            DB::table('candidates')->updateOrInsert(
                ['email' => $c['email']],
                [
                    'hr_id' => $hrId,
                    'company_name' => $c['company_name'] ?? 'General',
                    'job_title' => $c['job_title'] ?? null,
                    'name' => $c['name'],
                    'phone' => $c['phone'],
                    'location' => $c['location'],
                    'skills' => $c['skills'],
                    'experience' => $c['experience'],
                    'job_type' => $c['job_type'],
                    'notice_period' => $c['notice_period'],
                    'current_ctc' => $c['current_ctc'],
                    'expected_ctc' => $c['expected_ctc'],
                    'status' => $c['status'] ?? 'Applied',
                    'resume' => $c['resume'],
                    'edited_resume' => $c['edited_resume'] ?? null,
                    'note' => $c['note'],
                    'last_updated_by' => $c['last_updated_by'] ?? null,
                    'is_highlighted' => $c['is_highlighted'] ?? 0,
                    'created_at' => $c['created_at'],
                    'updated_at' => $c['updated_at'],
                ]
            );

            if (Schema::hasTable('students')) {
                DB::table('students')->updateOrInsert(
                    ['email' => $c['email']],
                    [
                        'hr_id' => $hrId,
                        'name' => $c['name'],
                        'phone' => $c['phone'],
                        'current_ctc' => (string)($c['current_ctc'] ?? '0'),
                        'expected_ctc' => (string)($c['expected_ctc'] ?? '0'),
                        'skills' => $c['skills'],
                        'location' => $c['location'],
                        'job_type' => $c['job_type'],
                        'experience' => (int)$c['experience'],
                        'notice_period' => $c['notice_period'],
                        'note' => $c['note'],
                        'resume' => $c['resume'] ?? '',
                        'company_resume' => $c['edited_resume'] ?? null,
                        'is_highlighted' => $c['is_highlighted'] ?? 0,
                        'created_at' => $c['created_at'],
                        'updated_at' => $c['updated_at'],
                    ]
                );
